#!/bin/sh
# Regenerate the WIT interop bindings (lib/src/components) from wit/ for
# both composition roots: the pipes engine (tina:probe/engine-probe) and
# the full TUI (tina:probe/tui-app). witgen clears its output directory on
# every run, so each world is generated into its own staging directory and
# the union is merged into lib/src/components; files generated by both
# worlds must be identical (checked). Local builds need the branch-tip
# wasm_tools (gitignored pubspec_overrides.yaml) on the pinned edge SDK:
# DART=/path/to/edge/dart sh tool/generate.sh. CI stays on the committed
# pins and does not run this script.
set -e
cd "$(dirname "$0")/.."
DART="${DART:-dart}"
"$DART" run wasm_tools witgen -i wit -w "tina:probe/engine-probe" -o .dart_tool/witgen-engine
"$DART" run wasm_tools witgen -i wit -w "tina:probe/tui-app" -o .dart_tool/witgen-tui

mkdir -p lib/src/components
cp -r .dart_tool/witgen-engine/. lib/src/components/
ls .dart_tool/witgen-engine > .dart_tool/witgen-engine-files
ls .dart_tool/witgen-tui > .dart_tool/witgen-tui-files
for f in $(comm -12 .dart_tool/witgen-engine-files .dart_tool/witgen-tui-files); do
  cmp -s ".dart_tool/witgen-engine/$f" ".dart_tool/witgen-tui/$f" || {
    echo "CONFLICT: $f differs between the engine and TUI worlds" >&2
    exit 1
  }
done
cp -r .dart_tool/witgen-tui/. lib/src/components/
echo "merged: $(ls lib/src/components | wc -l) files"
